pm.test("Status code is 200", function () {
    pm.response.to.have.status(200);
});

const responseText = pm.response.text().trim();
const match = responseText.match(/Auth_token:\s*([^\s"']+)/);

pm.test("Response contains authentication token", function () {
    pm.expect(match, "Expected an Auth_token response").to.not.be.null;
});

if (match) {
    const token = match[1].replace(/^["']+|["']+$/g, "");

    pm.collectionVariables.set("authToken", token);
}

const savedToken = pm.collectionVariables.get("authToken");

pm.test("Authentication token was saved correctly", function () {
    pm.expect(savedToken).to.be.a("string").and.not.empty;
    pm.expect(savedToken).not.to.include('"');
    pm.expect(savedToken).not.to.include("'");
});

