    pm.response.to.have.status(200);
});

pm.test("Invalid credentials return an error message", function () {
    const body = pm.response.json();

    pm.expect(body).to.have.property("errorMessage");
    pm.expect(body.errorMessage).to.be.a("string").and.not.empty;
});

pm.test("Error message identifies the login failure", function () {
    const body = pm.response.json();

    pm.expect(body.errorMessage).to.include("Wrong password");
