pm.test("Successful cart response is valid JSON", function () {
    if (pm.response.code === 200) {
        pm.expect(
            () => pm.response.json(),
            "Expected valid JSON for a successful cart response"
        ).to.not.throw();
    }
});

const token = String(
    pm.collectionVariables.get("authToken") || ""
).trim().replace(/^["']+|["']+$/g, "");

const productId = Number(
    pm.variables.replaceIn("{{productId}}")
);
const cartId = pm.variables.replaceIn("{{$guid}}");

if (!token) {
    throw new Error("Missing authToken. Run Login first.");
}

if (!Number.isInteger(productId) || productId <= 0) {
    throw new Error("productId must resolve to a positive integer.");
}

const payload = {
    id: cartId,
    cookie: token,
    prod_id: productId,
    flag: true
};

// Replace the raw request body with properly serialized JSON.
pm.request.body.update({
    mode: "raw",
    raw: JSON.stringify(payload)
});

console.log("=== Cart Request Validation ===");
console.log("Cart ID present:", Boolean(cartId));
console.log("Product ID:", productId);
console.log("Token present:", Boolean(token));
console.log("Payload is valid JSON:", (() => {
    try {
        JSON.parse(JSON.stringify(payload));
        return true;
    } catch (error) {
        return false;
    }
})());
console.log("=== End Validation ===");

